// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 deposit, uint256 value) public {
        vm.assume(deposit <= VALUE_CAP);
        // Admissible domain: fund the contract with a positive deposit, then ask
        // to withdraw strictly more than the contract holds.
        deposit = bound(deposit, 1, 1e30);
        value = bound(value, deposit + 1, deposit + 1e30);

        vm.deal(address(this), deposit);
        (bool ok, ) = address(c).call{value: deposit}("");
        assertTrue(ok); // deposit accepted via fallback; only setup check

        // owner == address(this), so withdraw pays out to the test contract.
        vm.prank(address(this));
        try c.withdraw(value) {
            // If it succeeds, it must have taken exactly value... but value > balance,
            // so reference never lands here.
        } catch {
            // Reference reverts here and leaves the balance untouched.
        }

        // General rule: a withdrawal request for more than the balance must be
        // rejected: the contract still holds exactly what was deposited.
        assertTrue(address(c).balance == deposit);
    }
}
